using System;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warcraft.NET.Files.WMO.WorldMapObject.Wotlk;

namespace Warcraft.NET.Tests
{
    [TestClass]
    public class WorldMapObjectGroupGeometryTests
    {
        [TestMethod]
        public void LoadBinaryData_ReadsRealTbcWallpostMogpWrapper()
        {
            // Extracted from C:\Program Files (x86)\Smolderforge\Data\common.MPQ,
            // world\wmo\azeroth\buildings\keepwall\wallpost01_000.wmo.
            // This is the complete 17,054-byte group file: MVER followed by one 17,034-byte
            // MOGP payload containing its 68-byte header and nested MOPY, MOVI, and MOVT chunks.
            byte[] data = Convert.FromBase64String(RealTbcWallpostGroupFixture);

            var group = new WorldMapObjectGroupGeometry(data);

            Assert.AreEqual(17054, data.Length);
            Assert.IsNotNull(group.Header);
            Assert.AreEqual((uint)17034, group.MogpChunkSize);
            Assert.AreEqual(371, group.Vertices.Length);
            Assert.AreEqual(1044, group.Indices.Length);
            Assert.AreEqual(348, group.TriangleMaterials.Length);
            Assert.AreEqual(-9.064668f, group.Vertices[0].X);
            Assert.AreEqual(5.2334867f, group.Vertices[0].Y);
            Assert.AreEqual(-7.2534776f, group.Vertices[0].Z);
            Assert.AreEqual((ushort)0, group.Indices[0]);
            Assert.AreEqual((ushort)0x0360, group.TriangleMaterials[0]);
        }

